arguments.new_string:
    limit = _MAX_LIMIT if page_size is None else min(page_size, _MAX_LIMIT)
    path = f"/v2/{resource}"
    # Filters go on the first request only; the cursor carries them afterwards.
    params = dict(filters or {})
    params["limit"] = str(limit)
    out: list[dict] = []
    while True:
        r = _send(transport, path, params, sleep, now)
        page = json.loads(r.body)
        out += page["data"]
        if not page.get("has_more"):
            return out
        params = {"limit": str(limit), "cursor": page["next_cursor"]}


_MAX_LIMIT = 200
_MAX_ATTEMPTS = 4


def _header(headers: dict[str, str], name: str) -> str | None:
    for k, v in headers.items():
        if k.lower() == name:
            return v
    return None


def _error_code(r: Response) -> str:
    try:
        return str(json.loads(r.body)["error"]["code"])
    except Exception:
        return "unknown"


def _retry_delay(r: Response, now: Callable[[], datetime]) -> float:
    default = 2.0 if r.status == 503 else 1.0
    value = _header(r.headers, "retry-after")
    if value is None:
        return default
    value = value.strip()
    if value.isascii() and value.isdigit():
        return float(int(value))
    try:
        when = parsedate_to_datetime(value)
    except (TypeError, ValueError):
        return default
    if when is None:
        return default
    if when.tzinfo is None:
        when = when.replace(tzinfo=timezone.utc)
    return max(0.0, (when - now()).total_seconds())


def _send(transport, path, params, sleep, now) -> Response:
    for attempt in range(_MAX_ATTEMPTS):
        r = transport(path, dict(params))
        if r.status == 200:
            return r
        if r.status not in (429, 503) or attempt == _MAX_ATTEMPTS - 1:
            raise ApiError(r.status, _error_code(r))
        delay = _retry_delay(r, now)
        if delay > 0:
            sleep(delay)
    raise AssertionError("unreachable")
